1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: unknown[];
4	}
5	
6	export interface ScenarioResults {
7	  results: unknown[];
8	}
9	
10	export const runScenario = (scenario: Scenario): ScenarioResults => {
11	  return { results: scenario.steps.map(() => ({ premium: 5 })) };
12	};
