1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case and base premiums ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("a sword → base premium 100 G, premium 105 G with fee");
15	  it.todo("an amulet → base premium 60 G, premium 65 G with fee");
16	  it.todo("a staff → base premium 80 G, premium 85 G with fee");
17	  it.todo("a potion → base premium 40 G, premium 45 G with fee");
18	  it.todo("a single rune (component) → base premium 25 G, premium 30 G with fee");
19	  it.todo("a single moonstone (component) → base premium 25 G, premium 30 G with fee");
20	
21	  // --- Building block of 3 alike components ---
22	  it.todo("2 runes → 50 G base premium (no block)");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium (no block)");
26	
27	  // --- "Alike" components: same type, not same family ---
28	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
29	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
30	
31	  // --- Item-specific modifiers ---
32	  it.todo("a cursed sword adds a 50 % risk surcharge → base 100 G + 50 G");
33	  it.todo("a sword with enchantment 5 adds a 30 % surcharge → base 100 G + 30 G");
34	  it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
35	  it.todo("a cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30)");
36	
37	  // --- Policy-wide modifiers ---
38	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
39	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
40	  it.todo("first insurance carries a 10 % initial assessment surcharge");
41	  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
42	  it.todo("the third quote in a scenario also receives the 15 % follow-up contract discount");
43	  it.todo(
44	    "each item in a quote is treated as a first insurance regardless of customer history — the 10 % surcharge applies on a follow-up contract too",
45	  );
46	
47	  // --- Modifier scope on multi-item policies ---
48	  it.todo(
49	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
50	  );
51	  it.todo(
52	    "policy-wide modifiers apply to the policy base premium (sum of item base premiums), the processing fee is added at the very end",
53	  );
54	
55	  // --- Rounding in the MHPCO's favour ---
56	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
57	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
58	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
59	
60	  // --- Claim: standard reimbursement ---
61	  it.todo(
62	    "regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible)",
63	  );
64	  it.todo(
65	    "damage to a rune (no enchantment level or material), damage 200 G → payout 100 G (full reimbursement minus deductible)",
66	  );
67	
68	  // --- Claim: special clauses ---
69	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
70	  it.todo(
71	    "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause: full reimbursement, then deductible)",
72	  );
73	  it.todo(
74	    "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)",
75	  );
76	  it.todo(
77	    "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; the 50 % rule wins, then deductible)",
78	  );
79	
80	  // --- Deductible per damage event ---
81	  it.todo(
82	    "a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible applies once per damaged item)",
83	  );
84	
85	  // --- Cap ---
86	  it.todo("a policy covers a sword and an amulet → insurance sum 1600 G, cap 3200 G");
87	  it.todo(
88	    "a cursed sword (premium with modifiers 165 G) → cap 2000 G (based on the unmodified insurance value)",
89	  );
90	  it.todo(
91	    "a policy covers a sword and 3 runes (a block) → insurance sum 1750 G; the block discount affects the premium only",
92	  );
93	  it.todo(
94	    "sword insured (cap 2000 G), two successive claims of 1500 G each → first claim payout 1400 G, remainingCap 600 G",
95	  );
96	  it.todo(
97	    "second successive claim of 1500 G → payout 600 G (reduced to the remaining cap), remainingCap 0 G",
98	  );
99	
100	  // --- Multiple items of the same type ---
101	  it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
102	  it.todo(
103	    "a dragon attack damages both swords (two sword damage entries) → each entry is a separate damage with its own deductible",
104	  );
105	  it.todo(
106	    "more damage entries of a type than the policy covers (two sword damages, one sword insured) → the whole claim is rejected with an error",
107	  );
108	
109	  // --- Error cases ---
110	  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
111	  it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
112	  it.todo("claim references a damage entry with an unknown item type → error");
113	  it.todo("claim contains a damage entry with amount -200 → error");
114	
115	  // --- Integration examples ---
116	  it.todo(
117	    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
118	  );
119	  it.todo(
120	    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
121	  );
122	
123	  // --- Scenario / results shape ---
124	  it.todo("results array has the same length and order as the input steps");
125	  it.todo("a claim step refers to the policy created by an earlier quote step via its zero-based step index");
126	});
